-- ---------------------------------------------------------------------------
-- 004. Website menu and channel
--
-- Run after 003_owner_setup.sql.
--
-- Adds the "Website" order channel and the live menu from
-- https://thecakeslicefactory.com/ to the product catalogue. The import is
-- idempotent: website_id uniquely identifies each menu item, so running this
-- file again refreshes names, categories and prices without creating duplicates
-- or resetting stock, type and status choices already adjusted in the app.
-- ---------------------------------------------------------------------------

alter type public.order_channel add value if not exists 'website';

alter table public.products add column if not exists website_id text;

-- Recreate the index so an earlier partial version cannot block the upsert
-- conflict target below.
drop index if exists public.uq_products_website_id;
create unique index uq_products_website_id
  on public.products(website_id);

insert into public.products (
  website_id, name, sku, kind, category, flavour, size, unit, price,
  cost_price, stock_qty, low_stock_at, track_stock, image_url, description, status
) values
